import React from 'react';
import ReactDOM from 'react-dom';
import { FormGroup, RadioButtonGroup, RadioButton, Checkbox } from 'carbon-components-react';

// Example using new legendId API (once patched)
function SettingsMenu() {
  return (
    <div className="settings-menu">
      {/* FormGroup example */}
      <FormGroup
        legendText="Select options"
        legendId="settings-options-legend"
        className="my-form-group"
      >
        <Checkbox id="opt-1" labelText="Option 1" />
        <Checkbox id="opt-2" labelText="Option 2" />
      </FormGroup>

      {/* RadioButtonGroup example */}
      <RadioButtonGroup
        name="row-height"
        legendText="Row height"
        legendId="row-height-label"
        orientation="vertical"
        labelPosition="right"
        valueSelected="medium"
      >
        <RadioButton value="small" labelText="Small" />
        <RadioButton value="medium" labelText="Medium" />
        <RadioButton value="large" labelText="Large" />
      </RadioButtonGroup>
    </div>
  );
}

ReactDOM.render(<SettingsMenu />, document.getElementById('root'));
